package in.finseq.insurance;
import android.app.*;import android.content.*;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import org.json.*;
public class PhysicalCopyRegisterActivity extends FinseqActivity{
 LinearLayout list;EditText search;JSONArray rows=new JSONArray();int cursor,shown;Button more;
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout root=Ui.column(this);Ui.appHeader(root,this,"Physical Copy Register");LinearLayout body=Ui.contentColumn(this);root.addView(body);search=Ui.input(this,"Search vehicle no., policy, customer or insurer");body.addView(search);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);body.addView(list);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int a,int b,int c){render();}public void afterTextChanged(Editable e){}});Ui.setScreen(this,root,3);load();}
 void load(){Ui.run(this,new Runnable(){public void run(){try{JSONObject response=ApiClient.get(PhysicalCopyRegisterActivity.this,"/api/v1/sync");final JSONArray result=response.optJSONArray("policies");Ui.ui(PhysicalCopyRegisterActivity.this,new Runnable(){public void run(){rows=result==null?new JSONArray():result;render();}});}catch(final Exception error){Ui.ui(PhysicalCopyRegisterActivity.this,new Runnable(){public void run(){Ui.toast(PhysicalCopyRegisterActivity.this,error.getMessage());}});}}});}
 void render(){list.removeAllViews();cursor=shown=0;more=null;appendPage();}
 void appendPage(){if(more!=null){list.removeView(more);more=null;}String q=search.getText().toString().trim().toLowerCase();int page=0;for(;cursor<rows.length()&&page<50;cursor++){JSONObject p=rows.optJSONObject(cursor);if(p==null)continue;String hay=(p.optString("customer")+" "+p.optString("policy_number")+" "+p.optString("insurer")+" "+p.optString("vehicle")).toLowerCase();if(!hay.contains(q))continue;page++;shown++;addPolicy(p);}if(cursor<rows.length()){more=Ui.outlineButton(this,"Show next 50 · "+shown+" shown");more.setOnClickListener(new View.OnClickListener(){public void onClick(View v){appendPage();}});list.addView(more);}else if(shown==0)list.addView(Ui.sub(this,"No policy records found."));else list.addView(Ui.sub(this,shown+" policy records shown."));}
 void addPolicy(JSONObject p){LinearLayout card=Ui.card(this);card.addView(Ui.text(this,p.optString("customer","Client"),17,true));card.addView(Ui.sub(this,p.optString("policy_number")+" · "+p.optString("insurer")));card.addView(Ui.text(this,"Vehicle No.: "+(p.optString("vehicle").isEmpty()?"—":p.optString("vehicle")),15,true));card.addView(Ui.sub(this,p.optString("type")+" · "+p.optString("subtype")+" · Expiry "+p.optString("expiry_date")));final int id=p.optInt("id");Button details=Ui.button(this,"Policy details");details.setOnClickListener(new View.OnClickListener(){public void onClick(View v){startActivity(new Intent(PhysicalCopyRegisterActivity.this,PolicyDetailActivity.class).putExtra("policy_id",id));}});card.addView(details);Button preview=Ui.outlineButton(this,"Preview PDF");preview.setEnabled(p.optBoolean("has_pdf"));preview.setOnClickListener(new View.OnClickListener(){public void onClick(View v){startActivity(new Intent(PhysicalCopyRegisterActivity.this,PdfPreviewActivity.class).putExtra("policy_id",id));}});card.addView(preview);Button share=Ui.greenButton(this,"Share policy copy");share.setEnabled(p.optBoolean("has_pdf"));share.setOnClickListener(new View.OnClickListener(){public void onClick(View v){share(id);}});card.addView(share);list.addView(card);}
 void share(final int id){PolicySharing.whatsapp(this,id,false);}
}
